// Two intervals a and b overlap when:
fun overlaps(a: IntArray, b: IntArray): Boolean =
    a[0] <= b[1] && b[0] <= a[1]

// Strict version (touching edges do not count):
fun overlapsStrict(a: IntArray, b: IntArray): Boolean =
    a[0] < b[1] && b[0] < a[1]

// Merged interval
// start = minOf(a[0], b[0])
// end   = maxOf(a[1], b[1])

fun merge(intervals: Array<IntArray>): Array<IntArray> {
    if (intervals.isEmpty()) return arrayOf()
    intervals.sortBy { it[0] }                    // sort by start
    val result = mutableListOf<IntArray>()
    var current = intervals[0]
    for (i in 1 until intervals.size) {
        val next = intervals[i]
        if (next[0] <= current[1]) {              // overlap
            current[1] = maxOf(current[1], next[1])
        } else {
            result.add(current)                   // no overlap, save and move on
            current = next
        }
    }
    result.add(current)
    return result.toTypedArray()
}
// Time: O(n log n)   Space: O(n)

fun insert(intervals: Array<IntArray>, newInterval: IntArray): Array<IntArray> {
    val result = mutableListOf<IntArray>()
    var i = 0
    val n = intervals.size
    // 1. Add all intervals that end before the new one starts
    while (i < n && intervals[i][1] < newInterval[0]) {
        result.add(intervals[i++])
    }
    // 2. Merge all intervals that overlap with the new one
    while (i < n && intervals[i][0] <= newInterval[1]) {
        newInterval[0] = minOf(newInterval[0], intervals[i][0])
        newInterval[1] = maxOf(newInterval[1], intervals[i][1])
        i++
    }
    result.add(newInterval)
    // 3. Add the rest
    while (i < n) result.add(intervals[i++])
    return result.toTypedArray()
}
// Time: O(n)   Space: O(n)

fun canAttendMeetings(intervals: Array<IntArray>): Boolean {
    intervals.sortBy { it[0] }
    for (i in 1 until intervals.size) {
        if (intervals[i][0] < intervals[i - 1][1]) return false
    }
    return true
}
// Time: O(n log n)   Space: O(1) extra

import java.util.PriorityQueue

fun minMeetingRooms(intervals: Array<IntArray>): Int {
    intervals.sortBy { it[0] }
    val endTimes = PriorityQueue<Int>()           // earliest ending meeting on top
    for (meeting in intervals) {
        if (endTimes.isNotEmpty() && endTimes.peek() <= meeting[0]) {
            endTimes.poll()                       // reuse that room
        }
        endTimes.add(meeting[1])
    }
    return endTimes.size                          // rooms in use
}
// Time: O(n log n)   Space: O(n)

fun minMeetingRoomsSweep(intervals: Array<IntArray>): Int {
    val starts = IntArray(intervals.size) { intervals[it][0] }.also { it.sort() }
    val ends = IntArray(intervals.size) { intervals[it][1] }.also { it.sort() }
    var rooms = 0
    var maxRooms = 0
    var e = 0
    for (s in starts.indices) {
        if (starts[s] >= ends[e]) {
            e++                                    // a meeting finished
        } else {
            rooms++                                // need one more room
        }
        maxRooms = maxOf(maxRooms, rooms)
    }
    return maxRooms
}
// Time: O(n log n)   Space: O(n)

fun eraseOverlapIntervals(intervals: Array<IntArray>): Int {
    if (intervals.isEmpty()) return 0
    intervals.sortBy { it[1] }                    // sort by END time (greedy)
    var end = intervals[0][1]
    var removed = 0
    for (i in 1 until intervals.size) {
        if (intervals[i][0] < end) {
            removed++                              // overlap: drop this one
        } else {
            end = intervals[i][1]                  // keep it
        }
    }
    return removed
}
// Time: O(n log n)   Space: O(1) extra
// Keep the interval that ends earliest to leave room for more

fun intervalIntersection(a: Array<IntArray>, b: Array<IntArray>): Array<IntArray> {
    val result = mutableListOf<IntArray>()
    var i = 0
    var j = 0
    while (i < a.size && j < b.size) {
        val start = maxOf(a[i][0], b[j][0])
        val end = minOf(a[i][1], b[j][1])
        if (start <= end) result.add(intArrayOf(start, end))
        // advance the pointer whose interval ends first
        if (a[i][1] < b[j][1]) i++ else j++
    }
    return result.toTypedArray()
}
// Time: O(n + m)   Space: O(1) extra (output not counted)

fun freeTime(schedules: List<List<IntArray>>): List<IntArray> {
    val all = schedules.flatten().sortedBy { it[0] }
    val gaps = mutableListOf<IntArray>()
    var end = all[0][1]
    for (i in 1 until all.size) {
        if (all[i][0] > end) {
            gaps.add(intArrayOf(end, all[i][0]))   // free time between meetings
        }
        end = maxOf(end, all[i][1])
    }
    return gaps
}
// Time: O(n log n)   Space: O(n)

fun findMinArrowShots(points: Array<IntArray>): Int {
    if (points.isEmpty()) return 0
    points.sortBy { it[1] }                        // sort by end
    var arrows = 1
    var end = points[0][1]
    for (i in 1 until points.size) {
        if (points[i][0] > end) {                  // no overlap with current arrow
            arrows++
            end = points[i][1]
        }
    }
    return arrows
}
// Time: O(n log n)   Space: O(1) extra
// Use Long comparisons if values reach Int limits

fun removeCoveredIntervals(intervals: Array<IntArray>): Int {
    // start ascending, and for equal starts, end descending
    intervals.sortWith(compareBy({ it[0] }, { -it[1] }))
    var count = 0
    var maxEnd = 0
    for (interval in intervals) {
        if (interval[1] > maxEnd) {
            count++                                // not covered by an earlier interval
            maxEnd = interval[1]
        }
    }
    return count
}
// Time: O(n log n)   Space: O(1) extra

import java.util.TreeMap

class MyCalendar {
    private val calendar = TreeMap<Int, Int>()    // start -> end

    fun book(start: Int, end: Int): Boolean {
        val prev = calendar.floorEntry(start)     // booking starting at or before 'start'
        val next = calendar.ceilingEntry(start)   // booking starting at or after 'start'
        if (prev != null && prev.value > start) return false
        if (next != null && next.key < end) return false
        calendar[start] = end
        return true
    }
}
// Each booking: O(log n)

// Maximum number of overlapping intervals at any time
fun maxOverlap(intervals: Array<IntArray>): Int {
    val events = mutableListOf<IntArray>()
    for ((start, end) in intervals) {
        events.add(intArrayOf(start, 1))           // +1 at start
        events.add(intArrayOf(end, -1))            // -1 at end
    }
    // at equal times, process ends (-1) before starts (+1)
    events.sortWith(compareBy({ it[0] }, { it[1] }))
    var current = 0
    var best = 0
    for (e in events) {
        current += e[1]
        best = maxOf(best, current)
    }
    return best
}
// Time: O(n log n)   Space: O(n)
